  getAvailableLanguages(): any;
  onLanguageChanged(callback: any): any;
  startIdeLogin(): any;
  getIdeLoginStatus(): any;
  logoutIdeAccount(): any;
  cloudSyncRequest(payload: any): any;
  backupSettingsToCloud(): any;
  getSettingsBackupInfo(): any;
  syncSettingsFromCloud(): any;
  onIdeLoginUpdated(callback: any): any;
  onIdeLoginError(callback: any): any;
  getRecentFiles(): any;
  openRecentFile(filePath: any): any;
  getFileHistory(): any;
  addToFileHistory(filePath: any): any;
  openFileFromHistory(filePath: any): any;
  clearFileHistory(): any;
  saveLastOpenTabs(tabs: any): any;
  getLastOpenTabs(): any;
  onMenuOpenFileHistory(callback: any): any;
  relaunchApp(): any;
  clipboardWriteText(text: any): any;
  clipboardReadText(): any;
  walkDirectory(dirPath: any, options: any): any;
  lspStart(options: any): any;
  lspStop(): any;
  lspRestart(options: any): any;
  lspRequest(method: any, params: any, requestId: any): any;
  lspCancel(requestId: any): any;
  lspApplyEditResult(requestId: any, result: any): any;
  lspNotify(method: any, params: any): any;
  onLspNotification(callback: any): any;
